import { getNotificationStatus, toggleNotifications } from './actions'

export default async function Home() {
  const isEnabled = await getNotificationStatus()

  return (
    <main className="p-4">
      <h1 className="text-2xl font-bold mb-4">Notification Settings</h1>

      <div className="flex items-center gap-4">
        <p>
          Notifications are currently: <strong>{isEnabled ? 'ON' : 'OFF'}</strong>
        </p>

        <form action={toggleNotifications}>
          <button 
            type="submit"
            className={`px-4 py-2 rounded ${
              isEnabled 
                ? 'bg-red-500 hover:bg-red-600 text-white' 
                : 'bg-green-500 hover:bg-green-600 text-white'
            }`}
          >
            {isEnabled ? 'Disable Notifications' : 'Enable Notifications'}
          </button>
        </form>
      </div>
    </main>
  )
}

